import{_ as s,a0 as a,w as i,s as u,ao as d,I as p,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"來自歐洲的一個開源 3D 打印 VR 頭盔項目 | LCTT x X-CMD","titleTemplate":false,"description":"來自歐洲的一個開源 3D 打印 VR 頭盔項目 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"來自歐洲的一個開源 3D 打印 VR 頭盔項目 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"來自歐洲的一個開源 3D 打印 VR 頭盔項目 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220915 A Project For An Open Source 3D-Printed VR Headgear From Europe","title":"來自歐洲的一個開源 3D 打印 VR 頭盔項目","tag":"202209","desc":""},"relativePath":"202209/20220915 A Project For An Open Source 3D-Printed VR Headgear From Europe.md","filePath":"[post].md"}'),l={name:"202209/20220915 A Project For An Open Source 3D-Printed VR Headgear From Europe.md"};function m(f,e,T,S,g,D){const r=a("Link");return i(),u("div",null,[e[15]||(e[15]=d('<h1 id="來自歐洲的一個開源-3d-打印-vr-頭盔項目" tabindex="-1">來自歐洲的一個開源 3D 打印 VR 頭盔項目 <a class="header-anchor" href="#來自歐洲的一個開源-3d-打印-vr-頭盔項目" aria-label="Permalink to “來自歐洲的一個開源 3D 打印 VR 頭盔項目”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/virtual-reality-4-1536x864.jpg" alt=""></p><blockquote><p>三家歐洲企業創建了一個 6 GHz WiFi 6E 無線開源虛擬現實頭盔。</p></blockquote><p>捷克 3D 打印專家 Prusa Research 公司正在與模擬器開發商 Vrgineers 和英國的 Somnium Space 合作開發 Somnium VR ONE 頭盔。這款產品可以連接或者獨立使用，旨在儘可能地開放，來改變虛擬現實市場中受限的供應。</p><p>由於 Android 11 操作系統是一個開源的操作系統，其源代碼是公開的，因此它將在不受限制的商業許可下出售。其中央處理單元是高通驍龍 XR2 CPU，支持 microSD 存儲卡，並擁有 8GB 的LPDDR5 內存和 512GB UFS 閃存。</p><p>它採用新的 6 GHz 的 WiFi 6E 高帶寬無線協議，而不是目前擁擠的 5GHz 和 2.4GHz WiFi頻率，以實現更高的帶寬和低延遲連接。它包括兩個 3.2 英寸 2880RGB * 2880 快速液晶屏幕，具有 120 度水平視野和 100 度垂直視野。</p><p>它具有兩個用於外部小工具的 USB-C 10 Gbit/s 鏈路，和一個 USB-C USB2.0 電池組（USB3.2 Gen2）。Somnium Space 與布拉格的 VRgineers 合作，在線銷售電子產品和獨有的鏡頭，使用户能夠 3D 打印自己的頭盔，此外，也會提供完整的頭盔。</p><p>該企業於 2012 年在布拉格成立，已經擁有 700 多名員工。開源的 Prusa i3 design 是世界上使用最廣泛的 3D 打印機，每月從布拉格直接向 160 多個國家運送超過 10000 台 Original Prusa 打印機。</p><p><ruby>合成訓練環境<rt>Synthetic Training Environments</rt></ruby>（STE）是由捷克共和國的模擬器開發商 VRgineers 向企業和政府客户提供的。它創造了被稱為 XTAL 的專業 8K 頭盔，該頭盔被 NASA、空客防務與航天公司和 BAE Systems 公司使用，目前在布拉格、布爾諾和拉斯維加斯擁有一支由 50 名專家組成的國際團隊。</p><p>總部位於倫敦的 Somnium Space 是一個建立在區塊鏈上的開放、社交和永久虛擬現實平台。由於其獨特的 NFT 的去中心化經濟，用户可以擁有、交易和交換數字商品而無需獲得授權。它已經與高通公司和 Ultraleap 公司在 Lynx R-1 上進行了合作，這是一個獨立的增強現實（AR）頭盔設計。</p><hr>',11)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),o(r,{href:"https://www.opensourceforu.com/2022/09/a-project-for-an-open-source-3d-printed-vr-headgear-from-europe/"},{default:n(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/09/a-project-for-an-open-source-3d-printed-vr-headgear-from-europe/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=t("作者：",-1)),o(r,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:n(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),o(r,{href:"https://github.com/lkxed"},{default:n(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),o(r,{href:"https://github.com/zjsoftceo"},{default:n(()=>[...e[4]||(e[4]=[t("zjoftceo",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),o(r,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const P=s(l,[["render",m]]);export{C as __pageData,P as default};
